// RunSessionCommand submits a shell command for execution in a session and returns a command ID for tracking its progress. Use `wait` to stream status updates until the command finishes; set `logs` as well to stream execution output in real time.
//
// Executes a shell command inside a running session. The command runs asynchronously and returns immediately with a command ID that can be used to track its progress and retrieve its output. Optionally, use the `wait` parameter to stream the command status until completion.
//
// Parameters:
//
//	sessionId: The unique identifier of the session in which to execute the
//	command.
//	cmdId: The unique identifier of the command to stream logs for.
//	command: The executable or shell command to run. This is the program name
//	without arguments.
//	teamId: The Team identifier to perform the request on behalf of.
//	slug: The Team slug to perform the request on behalf of.
//	args: Arguments to pass to the command. Each argument should be a separate
//	array element.
//	cwd: The working directory in which to execute the command. Defaults to the
//	sandbox home directory if not specified.
//	env: Additional environment variables to set for this command. These are
//	merged with the sandbox environment.
//	sudo: Execute the command with root (superuser) privileges.
//	wait: If true, returns an ND-JSON stream that emits the command status when
//	started and again when finished. Useful for synchronously waiting for
//	command completion.
//	logs: If true, stream the logs of the command execution in real-time via
//	ND-JSON. This is only applicable if `wait` is also true.
//	timeout: Maximum duration in milliseconds the command may run before it is
//	killed with SIGKILL, up to 5 hours. Enforced at exec time, independently of
//	`wait`.
//	attachStdin: If true, keeps the command stdin open so it can be written to
//	with the stdin endpoint while the command runs. When false, the command
//	reads from an empty stdin.
func (sdk *SandboxesNamespace) RunSessionCommand(ctx context.Context, params RunSessionCommandParams, opts ...RequestOption) (*RunSessionCommandResponse, error) {
	return RunSessionCommand(ctx, sdk.config, params, opts...)
}

